  ('1c1895db-3389-5122-ac9a-0541d453aedd', null, (select id from public.skills where slug = 'write-g12-writing-with-evidence'), null, 'hard',
   $q$What does sentence 4 contribute to the writer's argument?$q$, $q$[{"text":"It points out that the store sold some items that did not work.","is_correct":false,"misconception_token":"literal-reading"},{"text":"It shows that the first stanza is the most important part of the poem.","is_correct":false,"misconception_token":"overstates-evidence"},{"text":"It shows the shift toward loss is hinted at even in the plainest part of the list.","is_correct":true},{"text":"It proves that the speaker had lost the keys to her father's store.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It shows the shift toward loss is hinted at even in the plainest part of the list.$q$, $q$By finding loss in the "keys with no locks," the writer shows the list form carries meaning from the very start, which supports the claim in sentence 2. Reading the keys as broken merchandise misses that the writer treats them as an image of lost purpose.$q$, 'draft', '75148bc6-f525-5088-86a9-1ccd2e3c3fb6')
